namespace FiveSmartFarmCreators.Ichu.Platform.OperationsMonitoring.Interfaces.Rest.Resources;

/// <summary>
///     Resource representing the attention of a pending alert. Status must be Acknowledged; the version is the one
///     last read by the client.
/// </summary>
/// <param name="Status">The requested status, which must be Acknowledged.</param>
/// <param name="Finding">What the user found.</param>
/// <param name="Action">What the user did.</param>
/// <param name="OperationId">The identifier generated by the client, reused on every retry.</param>
/// <param name="ExpectedVersion">The alert version last read by the client.</param>
public record AcknowledgeAlertResource(string? Status, string? Finding, string? Action, Guid OperationId, int? ExpectedVersion);
